#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        assert(x>=1 && y>=1 && x+y<n);
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    // Place elements 1..n-2 at positions 0..n-3. Last two will be forced.
    // Actually let's try to place all n elements.

    for(int placed=0; placed<n; placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        int remaining = n - placed; // elements from index placed..n-1 we care about
        // We operate on the full array of size n.

        // Step 1: bring element from pos to position n-1
        if(pos != n-1){
            // prefix size = pos+1, element is at end of prefix (index pos)
            // After op(x, y): [C|B|A]. Element at index pos (in A, last element of A) goes to index n-1.
            // We need x = pos+1. We need y such that x+y < n, y >= 1.
            // y can be anything from 1 to n-1-x = n-2-pos.
            // We need n-2-pos >= 1, i.e., pos <= n-3.
            if(pos <= n-3){
                doOp(pos+1, 1);
                // Element was at pos = x-1 (last of prefix A). After op, A goes to end.
                // New position = (y) + (n-x-y) + pos = 1 + (n-pos-2) + pos = n-1. Good.
            } else {
                // pos == n-2, and pos != n-1
                // Swap first and last: op(1,1) if n>2
                doOp(1, 1);
                // Recheck
                for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                if(pos==placed) continue;
                if(pos!=n-1){
                    if(pos<=n-3){
                        doOp(pos+1, 1);
                    } else {
                        doOp(1,1);
                        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                        if(pos==placed) continue;
                        if(pos!=n-1 && pos<=n-3) doOp(pos+1,1);
                    }
                    for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                    if(pos==placed) continue;
                }
            }
        }

        // Now element should be at n-1
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;
        if(pos!=n-1) continue; // shouldn't happen

        // Step 2: move from n-1 to position placed
        // op(x, 1): suffix=[p[n-1]], goes to front. Prefix of size x goes to end.
        // Element lands at position 0. We want it at position placed.
        // op with y = n-1-placed, x = 1: element at n-1 is in suffix. It goes to position 0..y-1.
        // Specifically p[n-1] goes to position 0. But placed spots before it are already placed.
        // Use x = n-1-placed, y=1. x+y = n-placed. Need < n => placed>0.
        if(placed>0){
            doOp(n-1-placed, 1);
        } else {
            if(n>2) doOp(n-2, 1);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
